        const token = localStorage.getItem("authToken");
          fetch('/update-inactive', {
            method: 'POST',
            headers: { 
              'Content-Type': 'application/json',
              'Authorization': token ? "Bearer " + token : ""
            },
            body: JSON.stringify({ staff_id: staffId, inactive: isInactive, token })
        })
