            const barcode = row.cells[1].textContent.toLowerCase();
            const isChecked = row.querySelector('input[type=checkbox]').checked;

            const matchSearch = name.includes(search) || barcode.includes(search);
            const matchStatus =
                status === 'all' ||
                (status === 'active' && !isChecked) ||
                (status === 'inactive' && isChecked);

            row.style.display = matchSearch && matchStatus ? '' : 'none';
        });
    }

    function sortTable(columnIndex) {
        const table = document.getElementById("staffTable");
        const tbody = table.tBodies[0];
        const rows = Array.from(tbody.rows);

        const asc = !table.dataset.sortAsc || table.dataset.sortAsc === "false";
        table.dataset.sortAsc = asc;

        rows.sort((a, b) => {
            const cellA = a.cells[columnIndex].textContent.trim().toLowerCase();
            const cellB = b.cells[columnIndex].textContent.trim().toLowerCase();
            return asc ? cellA.localeCompare(cellB) : cellB.localeCompare(cellA);
        });

        rows.forEach(row => tbody.appendChild(row));
    }
