function ctaDecrypt(sInput) {
    var icLen = sInput.length;
    var icNewText = "";
    var sInchar = "";

    for (var i = 0; i < icLen; i++) {
        sInchar = sInput.charAt(i);

        switch (sInchar.charCodeAt(0)) {
            case 192:
            case 193:
            case 194:
            case 195:
            case 196:
            case 197:
            case 198:
            case 199:
            case 200:
            case 201:
            case 202:
            case 203:
            case 204:
            case 205:
            case 206:
            case 207:
            case 208:
            case 209:
            case 210:
            case 211:
            case 212:
            case 213:
            case 214:
            case 215:
            case 216:
            case 217:
                sInchar = String.fromCharCode(sInchar.charCodeAt(0) - 127);
                break;

            case 218:
            case 219:
            case 220:
            case 221:
            case 222:
            case 223:
            case 224:
            case 225:
            case 226:
            case 227:
            case 228:
            case 229:
            case 230:
            case 231:
            case 232:
            case 233:
            case 234:
            case 235:
            case 236:
            case 237:
            case 238:
            case 239:
            case 240:
            case 241:
            case 242:
            case 243:
                sInchar = String.fromCharCode(sInchar.charCodeAt(0) - 121);
                break;

            case 244:
            case 245:
            case 246:
            case 247:
            case 248:
            case 249:
            case 250:
            case 251:
            case 252:
            case 253:
                sInchar = String.fromCharCode(sInchar.charCodeAt(0) - 196);
                break;

            case 32:
                sInchar = String.fromCharCode(32);
                break;

            default:
                sInchar = String.fromCharCode(sInchar.charCodeAt(0) - 0);
        }

        icNewText += sInchar;
    }

    return icNewText;
}

