// --- Robust time normalization → "HH:mm:ss" or null ---
function normalizeTime(input) {
  if (input == null) return null;
  let s = String(input).trim().toLowerCase();
  if (!s) return null;

  // accept forms like "9", "09", "900", "09:00", "9:00", "9.5", "9:30pm", "21", "21:15"
  const ampm = /(am|pm)$/.exec(s);
  s = s.replace(/[^0-9:.]/g, ''); // keep digits, colon, dot
  if (!s) return null;

  let h = 0, m = 0, sec = 0;

  if (s.includes(':')) {
    const parts = s.split(':').map(x => x.trim());
    h = parseInt(parts[0] || '0', 10);
    m = parseInt(parts[1] || '0', 10);
    sec = parseInt(parts[2] || '0', 10);
  } else if (s.includes('.')) {
    // "9.5" = 9 hours + 0.5*60 mins
    const f = parseFloat(s);
    if (isNaN(f)) return null;
    h = Math.floor(f);
    m = Math.round((f - h) * 60);
  } else {
    // "900" => 9:00, "0930" => 9:30, "21" => 21:00
    if (s.length <= 2) {
      h = parseInt(s, 10);
    } else if (s.length === 3) {
      h = parseInt(s.slice(0,1), 10);
      m = parseInt(s.slice(1,3), 10);
    } else {
      h = parseInt(s.slice(0, s.length-2), 10);
      m = parseInt(s.slice(-2), 10);
    }
  }

  if (ampm) {
    const suffix = ampm[1];
    if (suffix === 'am') {
      if (h === 12) h = 0;
    } else if (suffix === 'pm') {
      if (h < 12) h += 12;
    }
  }

  if ([h,m,sec].some(n => isNaN(n))) return null;
  if (h < 0 || h > 23 || m < 0 || m > 59 || sec < 0 || sec > 59) return null;

  const HH = String(h).padStart(2,'0');
  const MM = String(m).padStart(2,'0');
  const SS = String(sec).padStart(2,'0');
  return `${HH}:${MM}:${SS}`;
}

