function safeIso(value) {
    if (value === null || value === undefined) return null;

    const n = Number(value);
    if (!Number.isFinite(n) || n <= 0) return null;
    if (Math.abs(n) > 8640000000000000) return null;

    const d = new Date(n);
    if (isNaN(d.getTime())) return null;

    try {
        return d.toISOString();
    } catch (e) {
        return null;
    }
}

function pinStatus(p) {
    const now = Date.now();
    const start = Number(p.startDate || 0);
    const end = Number(p.endDate || 0);

    if (p.status === 0) return 'disabled';
    if (p.status === 1) {
        if (end > 0 && Number.isFinite(end) && end <= 8640000000000000 && end < now) {
            return 'expired';
        }
        if (start > now) {
            return 'scheduled';
        }
        return 'active';
    }

    if (end > 0 && Number.isFinite(end) && end <= 8640000000000000 && end < now) {
        return 'expired';
    }
    if (start > now) {
        return 'scheduled';
    }
    return 'active';
}

