msg._lockScan = scan;
node.status({ fill: 'green', shape: 'dot', text: `locks loaded: ${scan.allLocks.length}` });
return [null, msg, null];

const locks = Array.isArray(msg.payload) ? msg.payload : [];
const scan = msg._lockScan || {};
flow.set('ttlock_last_midnight_scan', {
    at: new Date().toISOString(),
    totalLocks: locks.length,
    startedAt: scan.startedAt || null
});
return null;

const config = flow.get('ttlock_config');
const token = flow.get('ttlock_token');
const lock = msg.payload || {};
const daily = msg._dailyPinBatch || {};

if (!config || !token || !token.accessToken) {
    msg.payload = {
        success: false,
