    'clientId=' + encodeURIComponent(config.clientId) +
    '&accessToken=' + encodeURIComponent(token.accessToken) +
    '&lockId=' + encodeURIComponent(lockId) +
    '&keyboardPwd=' + encodeURIComponent(daily.pin) +
    '&keyboardPwdName=' + encodeURIComponent(daily.pinName) +
    '&startDate=' + startDate +
    '&endDate=' + endDate +
    '&addType=2' +
    '&date=' + now;

