    lockId,
    lockAlias: lock.lockAlias || lock.lockName || lock.name || ('Lock ' + lockId),
    pin: daily.pin,
    pinName: daily.pinName,
    startDate,
    endDate,
    hours: 24,
    createdAt: daily.createdAt || new Date(now).toISOString(),
    batchDate: daily.batchDate || new Date(now).toISOString().slice(0, 10)
};

msg.url = 'https://api.sciener.com/v3/keyboardPwd/add';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/x-www-form-urlencoded' };
