        }

        msg.url = msg._originalRequest.url;
        msg.method = msg._originalRequest.method;
        msg.headers = msg._originalRequest.headers;
        msg.payload = msg._originalRequest.payload;

        node.status({
            fill: 'yellow',
            shape: 'ring',
            text: `lock ${msg._pinMeta && msg._pinMeta.lockId ? msg._pinMeta.lockId : ''} retry ${msg._retryCount}/${maxRetries}`
        });

        return [msg, null];
    }

    msg.payload = {
        success: false,
        msg: 'Gateway busy after max retries: ' + (resp.errmsg || 'The gateway is busy. Please try again later.'),
        error: resp.errmsg || 'The gateway is busy. Please try again later.',
        code: code,
        detail: resp,
        retries: msg._retryCount,
        lockId: msg._pinMeta ? msg._pinMeta.lockId : null,
        lockAlias: msg._pinMeta ? msg._pinMeta.lockAlias : null,
        pin: msg._pinMeta ? msg._pinMeta.pin : null,
        pinName: msg._pinMeta ? msg._pinMeta.pinName : null
    };
    return [null, msg];
}

node.status({});
return [null, msg];

const resp = msg.payload || {};
const meta = msg._pinMeta || {};

if (Number(resp.errcode) === 0 || resp.keyboardPwdId) {
    let log = flow.get('ttlock_midnight_pin_log') || [];

    log.push({
        at: new Date().toISOString(),
        lockId: meta.lockId,
        lockAlias: meta.lockAlias,
        keyboardPwdId: resp.keyboardPwdId || null,
        pin: meta.pin,
