    msg.payload = {
        success: true,
        lockId: meta.lockId,
        lockAlias: meta.lockAlias,
        keyboardPwdId: resp.keyboardPwdId || null,
        pin: meta.pin,
        pinName: meta.pinName,
        validFrom: new Date(meta.startDate).toISOString(),
        validUntil: new Date(meta.endDate).toISOString(),
        retries: Number(msg._retryCount || 0)
