let failLog = flow.get('ttlock_midnight_pin_log') || [];

failLog.push({
    at: new Date().toISOString(),
    lockId: meta.lockId || null,
    lockAlias: meta.lockAlias || null,
    keyboardPwdId: null,
    pin: meta.pin || null,
    pinName: meta.pinName || null,
