if (failLog.length > 5000) failLog = failLog.slice(-5000);
flow.set('ttlock_midnight_pin_log', failLog);

msg.payload = {
    success: false,
    lockId: meta.lockId || null,
    lockAlias: meta.lockAlias || null,
    pin: meta.pin || null,
    pinName: meta.pinName || null,
    validFrom: meta.startDate ? new Date(meta.startDate).toISOString() : null,
    validUntil: meta.endDate ? new Date(meta.endDate).toISOString() : null,
    retries: Number(msg._retryCount || 0),
    error: resp.errmsg || msg.payload?.error || 'Failed to add pin',
    code: resp.errcode ?? msg.payload?.code ?? null,
    detail: resp.errcode !== undefined ? resp : msg.payload?.detail || msg.payload,
    msg: (meta.pinName || '') + '(' + (meta.pin || '') + ') ' + (resp.errmsg || msg.payload?.error || 'Failed to add pin') + ' \r\n' + (meta.lockAlias || '')
