// Use the request host so it works with any domain
var host = 'ebtsuper.server.ubesvr.com';
if (msg.req && msg.req.headers && msg.req.headers.host) {
    host = msg.req.headers.host.split(':')[0];
}
var ssoUrl = 'https://sso.server.ubesvr.com/auth/login';
var callbackUrl = 'https://' + host + '/sso-callback';
if (msg.req && msg.req.query && msg.req.query.return) {
    callbackUrl += '?return=' + encodeURIComponent(msg.req.query.return);
}
var redirectUrl = ssoUrl + '?redirect=' + encodeURIComponent(callbackUrl);
