msg.headers = { 'Location': redirectUrl };
msg.payload = { redirectUrl: redirectUrl };
return msg;

// Parse cookies from request
var cookies = {};
if (msg.req && msg.req.headers && msg.req.headers.cookie) {
    msg.req.headers.cookie.split(";").forEach(function(c) {
