if (!ssoToken) {
    // No cookie -> output 2 (redirect to login)
    var redirectUrl = "/login";
    if (msg.req && msg.req.query && msg.req.query.return) {
        redirectUrl += "?return=" + encodeURIComponent(msg.req.query.return);
    }
    msg.statusCode = 302;
    msg.headers = { "Location": redirectUrl };
    msg.payload = "";
    return [null, msg];
}
try {
    var jwt = global.get("jwt");
    var secret = global.get("jwt-secret");
    var decoded = jwt.verify(ssoToken, secret);
    msg.staffBarcode = decoded.sub;
    msg.staffName = decoded.fullName || "";
    msg.staffRole = decoded.role || "staff";
    var bc = decoded.sub.replace(/'/g, "''");
    msg.topic = (
        "SELECT s.staff_id, s.docket_name, s.surname, s.given_names, "
        + "sg.group_id, dbo.ctaDecrypt(g.group_name) AS GroupName "
        + "FROM VIP_HO.dbo.Staff s "
        + "LEFT JOIN VIP_HO.dbo.Security_StaffGroups sg ON s.staff_id = sg.staff_id "
        + "LEFT JOIN VIP_HO.dbo.Security_Groups g ON sg.group_id = g.group_id "
        + "WHERE s.barcode = '" + bc + "'"
    );
    return [msg, null];
} catch (e) {
    var redirectUrl = "/login";
    if (msg.req && msg.req.query && msg.req.query.return) {
        redirectUrl += "?return=" + encodeURIComponent(msg.req.query.return);
    }
    msg.statusCode = 302;
    msg.headers = { "Location": redirectUrl };
    msg.payload = "";
    return [null, msg];
}

if (!msg.payload || (Array.isArray(msg.payload) && msg.payload.length === 0)) {
    msg.token = Buffer.from(msg.staffBarcode + "-" + Date.now()).toString("base64");
    msg.tokenExpiry = Date.now() + 60 * 60 * 1000;
    msg.staffEmail = msg.staffName || "";
    msg.groupId = 2;
    msg.groupName = "staff";
} else {
    var staff = Array.isArray(msg.payload) ? msg.payload[0] : msg.payload;
    msg.token = Buffer.from(msg.staffBarcode + "-" + Date.now()).toString("base64");
    msg.tokenExpiry = Date.now() + 60 * 60 * 1000;
    var firstName = staff.given_names || staff.docket_name || "";
    var lastName = staff.surname || "";
    msg.staffEmail = (firstName + " " + lastName).trim();
    msg.groupId = staff.group_id || 2;
    msg.groupName = staff.GroupName || "staff";
}
var sessions = global.get("sessions") || {};
sessions[msg.token] = { email: msg.staffEmail || msg.staffBarcode, expiry: msg.tokenExpiry };
global.set("sessions", sessions);
global.set("token:" + msg.token, { email: msg.staffEmail || msg.staffBarcode, expiry: msg.tokenExpiry });
var isAdmin = msg.groupId === -69 || (msg.groupName && msg.groupName.toLowerCase() === "administrator");
msg.isAdmin = isAdmin ? "true" : "false";
return msg;

// Clear both localStorage and SSO cookie
msg.headers = {
    'Set-Cookie': [
        'sso_token=; Max-Age=0; Domain=.ubesvr.com; Path=/; Secure; HttpOnly'
    ]
};
return msg;

